-- 具名本地seasonal-material-v1，原21/25/26页面保留；原运营配置未知。
-- 子实例先创建，父目录最后插入；既有窗口和运营编辑保持。
SET @p15_month = DATE_FORMAT(UTC_TIMESTAMP() + INTERVAL 8 HOUR,'%Y%m');
SET @p15_start = TIMESTAMP(DATE_FORMAT(UTC_TIMESTAMP() + INTERVAL 8 HOUR,'%Y-%m-01')) - INTERVAL 8 HOUR;
SET @p15_start_ms = TIMESTAMPDIFF(MICROSECOND,'1970-01-01',@p15_start) DIV 1000;
SET @p15_end_ms = TIMESTAMPDIFF(MICROSECOND,'1970-01-01',TIMESTAMP(DATE_FORMAT(UTC_TIMESTAMP() + INTERVAL 8 HOUR,'%Y-%m-01')) + INTERVAL 1 MONTH - INTERVAL 8 HOUR) DIV 1000;
SET @p15_claim_ms = @p15_end_ms + 604800000;
SET @p15_source = CONVERT(X'' USING utf8mb4);
INSERT IGNORE INTO p1_period_instances(id,enabled,title,kind,mode,goal,rewards,start_at,end_at,reward_end_at,rank_places,rank_rewards,source) VALUES
