(CONCAT('totalLoginFestival_p4_festival_',@p15_month),0,'节日精灵补给','login_day','cumulative',1,'item_124,15',@p15_start_ms,@p15_end_ms,@p15_claim_ms,0,'',@p15_source),
(CONCAT('totalLoginUpdate_p4_update_',@p15_month),0,'新版三日补给','login_day','cumulative',3,'item_013,2;item_139,2',@p15_start_ms,@p15_end_ms,@p15_claim_ms,0,'',@p15_source);
INSERT IGNORE INTO p4_commerce_rules(id,shop_type,kind,enabled,start_at,end_at,claim_end_at,rules,source) VALUES(CONCAT('limitExchangeFestival_p4_festival_',@p15_month),0,'exchange',0,@p15_start_ms,@p15_end_ms,@p15_end_ms,X'',@p15_source);
INSERT IGNORE INTO p15_seasonal_bundles(id,kind,title,enabled,start_at,end_at,reward_end_at,children,source) VALUES
